// The cards on a GitHub board (a project), through the GitHub CLI: its items
// that are issues of the connected repository (and carry the factory's label,
// unless it takes in every card), each in the column of its Status field.
import { keptIn, withKept } from "@software-factory/core";
import { STAGES } from "../../api.js";
import { answer, ownerOf } from "../../github-cli.js";
import { Refused } from "../../refused.js";
import { addToBoard, putInColumn, WAITING } from "./on-board.js";
import { blockedBy, relationsOf } from "./relations.js";
import { readProject } from "./items.js";
import { heldArgs, labelArgs, planOf, stuckArgs, typeEdit, withPlan, } from "../../cards/cards.js";
export function githubCards(cli, board, waiting = WAITING) {
    const cards = new GitHubCards(cli, board, waiting);
    return {
        list: () => cards.list(),
        show: (number) => cards.show(number),
        move: (number, stage) => cards.move(number, stage),
        comment: (number, text) => cards.comment(number, text),
        create: (title, body, stage, made) => cards.create(title, body, stage, made),
        bring: (number) => cards.bring(number),
        writePlan: (number, plan) => cards.writePlan(number, plan),
        keepWork: (number, kept, held) => cards.keepWork(number, kept, held),
        dependOn: (number, on) => cards.dependOn(number, on),
        replace: (number, by) => cards.replace(number, by),
        setType: (number, type) => cards.setType(number, type),
        markStuck: (number, stuck) => cards.markStuck(number, stuck),
        remove: (number) => cards.remove(number),
    };
}
class GitHubCards {
    cli;
    board;
    owner;
    repo;
    waiting;
    constructor(cli, board, waiting) {
        this.cli = cli;
        this.board = board;
        this.waiting = waiting;
        this.owner = ownerOf(board.repository);
        this.repo = ["--repo", board.repository];
    }
    async list() {
        return (await this.project()).items.flatMap((item) => this.cardOf(item) ?? []);
    }
    async show(number) {
        const { card } = await this.find(number);
        const read = await this.issue(number, "body,comments");
        const related = await relationsOf(this.cli, this.board.repository, number);
        return {
            ...card,
            body: read.body,
            agreed: planOf(read.body) !== null,
            kept: keptIn(read.body),
            ...related,
            comments: read.comments.map((c) => ({
                author: c.author?.login ?? "",
                body: c.body,
                at: c.createdAt,
            })),
        };
    }
    async move(number, stage) {
        const { project, item } = await this.find(number);
        await this.setColumn(project.id, item.id, stage);
    }
    async comment(number, text) {
        await this.gh([
            "issue",
            "comment",
            String(number),
            ...this.repo,
            "--body",
            text,
        ]);
    }
    // A new card in the stage asked for (the backlog unless said): the issue,
    // told to `made` at once, added to the board and put in its column.
    async create(title, body, stage = "backlog", made = () => { }) {
        const label = this.board.label === "*" ? [] : ["--label", this.board.label];
        const url = (await this.gh([
            "issue",
            "create",
            ...this.repo,
            "--title",
            title,
            "--body",
            body,
            ...label,
        ])).trim();
        const number = Number(/\/issues\/(\d+)/.exec(url)?.[1]);
        made({ number, url });
        const { projectId, itemId } = await this.addToBoard(number, url);
        await this.setColumn(projectId, itemId, stage);
        return {
            number,
            title,
            stage,
            column: this.board.stages[stage],
            url,
            labels: label.slice(1),
            closed: false,
            waitsFor: [],
        };
    }
    // An issue made earlier, to be a card: already on the board, or added now.
    async bring(number) {
        const project = await this.project();
        if (project.items.some((item) => this.cardOf(item)?.number === number))
            return;
        const { url } = await this.issue(number, "url");
        await this.addToBoard(number, url);
    }
    // The issue put on the board, its item found there (on-board.ts).
    addToBoard(number, url) {
        const on = {
            owner: this.owner,
            board: this.board.board,
            waiting: this.waiting,
        };
        return addToBoard(this.cli, on, { number, url }, async () => {
            const project = await this.project();
            const item = project.items.find((one) => this.cardOf(one)?.number === number);
            return { projectId: project.id, itemId: item?.id ?? null };
        });
    }
    async writePlan(number, plan) {
        await this.editBody(number, (body) => withPlan(body, plan));
    }
    // The card's text, changed by `change`, written back when it differs.
    async editBody(number, change) {
        const { body } = await this.issue(number, "body");
        const written = change(body);
        if (written !== body)
            await this.gh([
                "issue",
                "edit",
                String(number),
                ...this.repo,
                "--body",
                written,
            ]);
    }
    // The card's piece of work: what it keeps in its text, and the label of the
    // team's stage that holds it.
    async keepWork(number, kept, held) {
        const { card } = await this.find(number);
        await this.editBody(number, (body) => withKept(body, kept));
        for (const args of heldArgs(number, card.labels, held, this.repo))
            await this.gh(args);
    }
    // The card's type as a label (made when GitHub has none of that name);
    // its other type labels come off.
    async setType(number, type) {
        const { card } = await this.find(number);
        if (type)
            await this.gh(labelArgs(type, this.repo));
        const edit = typeEdit(card.labels, type);
        if (edit.length > 0)
            await this.gh(["issue", "edit", String(number), ...this.repo, ...edit]);
    }
    // The stuck mark as a label (made when GitHub has none of that name).
    async markStuck(number, stuck) {
        const { card } = await this.find(number);
        for (const args of stuckArgs(number, card.labels, stuck, this.repo))
            await this.gh(args);
    }
    // GitHub's "blocked by": the card waits for the other one.
    async dependOn(number, on) {
        if (number === on)
            throw new Refused("A card can't depend on itself.");
        await this.find(number);
        await blockedBy(this.cli, this.board.repository, number, on);
    }
    // Closed as not planned, with a note on both cards pointing to the other.
    async replace(number, by) {
        if (number === by)
            throw new Refused("A card can't replace itself.");
        await this.find(number);
        await this.find(by);
        await this.comment(number, `Replaced by #${String(by)}, which does this now.`);
        await this.comment(by, `Replaces #${String(number)}.`);
        await this.gh([
            "issue",
            "close",
            String(number),
            ...this.repo,
            "--reason",
            "not planned",
        ]);
    }
    // Closed as not planned and taken off the board; the issue stays on GitHub.
    async remove(number) {
        const { card, item } = await this.find(number);
        if (card.stage === "doing")
            throw new Refused(`The builder is on #${String(number)}: stop it before deleting the card.`);
        if (!card.closed)
            await this.gh([
                "issue",
                "close",
                String(number),
                ...this.repo,
                "--reason",
                "not planned",
            ]);
        await this.gh([
            "project",
            "item-delete",
            String(this.board.board),
            "--owner",
            this.owner,
            "--id",
            item.id,
        ]);
    }
    // The card with that number, its item and the board.
    async find(number) {
        const project = await this.project();
        for (const item of project.items) {
            const card = this.cardOf(item);
            if (card?.number === number)
                return { project, item, card };
        }
        throw new Refused(`There is no card #${String(number)} on the board.`);
    }
    cardOf(item) {
        const { issue } = item;
        const { board } = this;
        if (issue?.repository !== board.repository)
            return null;
        if (board.label !== "*" && !issue.labels.includes(board.label))
            return null;
        return {
            number: issue.number,
            title: issue.title,
            stage: STAGES.find((stage) => board.stages[stage] === item.status) ?? null,
            column: item.status,
            url: issue.url,
            labels: issue.labels,
            closed: issue.closed,
            waitsFor: issue.waitsFor,
        };
    }
    async issue(number, fields) {
        return JSON.parse(await this.gh([
            "issue",
            "view",
            String(number),
            ...this.repo,
            "--json",
            fields,
        ]));
    }
    // The board's id and its items, each with its column and issue.
    project() {
        return readProject(this.gh.bind(this), this.owner, this.board.board);
    }
    // Puts the item in the column of the stage, as board.json matches them.
    setColumn(projectId, itemId, stage) {
        const { board, stages } = this.board;
        return putInColumn(this.cli, { owner: this.owner, board, column: stages[stage], stage }, { projectId, itemId });
    }
    async gh(args) {
        return answer(await this.cli.run(args));
    }
}
